<script setup lang="ts">
import {ref,onMounted} from 'vue'
import TierEditor from './TierEditor.vue'
import BillingEditor from './BillingEditor.vue'
import {Save,Settings2} from 'lucide-vue-next'
import {api,notify,subscriptionRegions,regionLabel,type Row} from '../lib'
const props=defineProps<{group:string;value:Row}>();const emit=defineEmits<{saved:[]}>();const form=ref<Row>(JSON.parse(JSON.stringify(props.value))),busy=ref(false),err=ref('')
const jsonText=ref(JSON.stringify(props.value.address_templates||props.value.items||[],null,2))
const proxies=ref<Row[]>([])
if(props.group==='proxy')form.value.global_id??=''
const checkoutPlans=[{id:'pro5x',name:'Pro 5x',default:'hosted'},{id:'pro',name:'Pro 20x',default:'hosted'},{id:'team',name:'Team 标准',default:'oaics'},{id:'team_premium',name:'Team 高级',default:'oaics'},{id:'plus',name:'Plus',default:'oaics',preset:true},{id:'go',name:'Go',default:'oaics',preset:true}]
if(props.group==='payment'){delete form.value.checkout_flow;form.value.subscription_flow??='cslive';form.value.checkout_type??='hosted';form.value.checkout_types={...Object.fromEntries(checkoutPlans.map(p=>[p.id,p.default])),...form.value.checkout_types}}
if(props.group==='scheduler')form.value.link_mode='long'
onMounted(async()=>{if(props.group==='proxy')try{proxies.value=(await api('/admin/resources')).items}catch(e){err.value=(e as Error).message}})
const fields:Record<string,Row[]>={
 payment:[{k:'activation_check_interval_seconds',n:'付款后订阅生效核实间隔（秒）',min:2,max:300},{k:'activation_check_limit',n:'订阅生效最多核实次数',min:1,max:120},{k:'subscription_wait_seconds',n:'订阅准备最长等待（秒）',min:30,max:1800},{k:'renewal_check_interval_seconds',n:'关闭续费核实间隔（秒）',min:5,max:300},{k:'renewal_check_limit',n:'关闭续费最多核实次数',min:1,max:60},{k:'enabled',n:'开放站内付款',type:'switch'},{k:'max_parallel',n:'付款任务总并发',min:1,max:20},{k:'per_user_parallel',n:'单客户付款并发',min:1,max:5},{k:'prepare_timeout_seconds',n:'报价准备超时（秒）',min:30,max:300},{k:'quote_timeout_seconds',n:'等待客户确认（秒）',min:30,max:600},{k:'result_timeout_seconds',n:'付款结果等待（秒）',min:30,max:600},{k:'requests_per_minute',n:'每客户每分钟准备次数',min:1,max:20}],
 proxy:[{k:'request_timeout_seconds',n:'每次上游请求超时（秒）',min:10,max:120}],
 risk:[{k:'login_per_minute',n:'每 IP 每分钟登录次数',min:1,max:100},{k:'api_per_minute',n:'每账号每分钟接口请求',min:10,max:10000},{k:'order_per_minute',n:'每账号每分钟创建订单',min:1,max:100},{k:'max_open_orders',n:'每账号未完成订单上限',min:1,max:500},{k:'max_topup',n:'单笔充值上限（R）',min:1,max:1000000,money:true},{k:'session_hours',n:'登录有效期（小时）',min:1,max:168},{k:'event_retention_days',n:'风控事件保留天数',min:7,max:365}],
 scheduler:[{k:'paused',n:'暂停队列领取',type:'switch'},{k:'max_parallel',n:'全局最大并发',min:1,max:100},{k:'per_user_parallel',n:'单账号最大并发',min:1,max:20},{k:'retry_limit',n:'安全失败最大重试次数',min:0,max:10},{k:'retry_delay_seconds',n:'重试间隔（秒）',min:5,max:3600},{k:'task_timeout_seconds',n:'任务超时（秒）',min:30,max:1800},{k:'queue_limit',n:'等待队列上限',min:1,max:10000},{k:'default_country',n:'默认订阅地区',type:'select',options:subscriptionRegions.map(r=>r.code)}],
 site:[{k:'name',n:'中文品牌',type:'text'},{k:'english_name',n:'英文名称',type:'text'},{k:'tagline',n:'品牌说明',type:'text'},{k:'registration_open',n:'开放自主注册',type:'switch'},{k:'support_url',n:'客服链接（http / https）',type:'text'},{k:'terms',n:'服务约定',type:'textarea'}],
 billing:[{k:'country',n:'默认付款账单国家',type:'fixed'}]
}
for(const f of fields[props.group]||[])if(f.money)form.value[f.k]/=100
async function save(){if(busy.value)return;busy.value=true;err.value='';try{const payload=JSON.parse(JSON.stringify(form.value));for(const f of fields[props.group]||[])if(f.money)payload[f.k]=Math.round(payload[f.k]*100);if(props.group==='proxy')payload.match_country=true;if(props.group==='tiers')payload.items=JSON.parse(jsonText.value);await api('/admin/settings/'+props.group,'PUT',payload);notify('配置已保存');emit('saved')}catch(e){err.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><TierEditor v-if="group==='tiers'" :value="value" @saved="emit('saved')"/><BillingEditor v-else-if="group==='billing'" :value="value"/><form v-else @submit.prevent="save"><div class="alert danger" v-if="err">{{err}}</div><div class="callout" v-if="group==='scheduler'">结账准备按队列、并发与重试间隔执行；上游创建结果不明时停止重发。付款并发及超时在付款配置中设置。</div><template v-if="group==='payment'"><section class="subscription-flow-settings"><h3>完整订阅流程</h3><p class="muted">提链、付款及后续使用同一套流程，保存后对新申请生效。</p><label class="subscription-flow-choice">订阅办理流程<select v-model="form.subscription_flow" aria-label="订阅办理流程"><option value="legacy">旧流程 · 脚本提链＋浏览器付款</option><option value="legacy_protocol">旧协议 · 脚本提链＋HTTP 付款</option><option value="cslive">新流程 · cs-live 完整流程</option><option value="cslive_browser">新提链＋旧浏览器付款</option></select><small>订阅办理执行所选完整流程，结账链接工具只执行该流程的提链部分。</small></label></section><div class="callout subscription-flow-summary"><b>当前流程：{{form.subscription_flow==='legacy'?'旧流程 · 脚本提链＋浏览器付款':form.subscription_flow==='legacy_protocol'?'旧协议 · 脚本提链＋HTTP 付款':form.subscription_flow==='cslive_browser'?'新提链＋旧浏览器付款':'新流程 · cs-live 完整流程'}}</b><p>整笔订阅沿用同一个后台代理，包括付款后的查询、刷新和续费处理。动态 IPRoyal 使用原 session 规则，动态 Cliproxy 每单使用独立 sid、有效 15 分钟；静态和其他厂商原样使用后台地址和凭据。付款前检查出口 IP，不一致或检查失败即停止。账单沿用本单随机抽取的资料。</p></div><section class="checkout-plan-settings"><h3>套餐结账链接</h3><p class="muted">由管理员逐项选择，新旧流程、订阅办理和结账链接页面共用。保存后仅新申请生效。</p><div class="form-grid"><label v-for="plan in checkoutPlans" :key="plan.id">{{plan.name}}<select v-model="form.checkout_types[plan.id]" :aria-label="plan.name+' 结账链接类型'"><option value="hosted">长链</option><option value="oaics">短链</option></select><small v-if="plan.preset">预设规则，当前尚未上架</small></label></div><p class="muted">长短链由套餐配置决定，四套完整流程共用。新流程和新提链＋旧浏览器付款需要完整 Session；旧浏览器短链付款需要 sessionToken 或会话 Cookie。旧协议遇官方验证时暂停，完成验证后只核实原交易。</p></section></template><template v-if="group==='proxy'"><div class="callout">按订单的订阅地区自动匹配代理。同地区没有空闲代理时排队；同一轮任务固定使用同一代理，所有提链请求均经该代理执行。</div><label>续费全局代理<select v-model="form.global_id"><option value="">未配置（续费任务等待）</option><option v-for="p in proxies" :key="p.id" :value="p.id" :disabled="!p.enabled">{{p.name}} · {{regionLabel(p.country)}}{{p.enabled?'':'（停用）'}}</option></select><small>仅用于续费管理菜单发起的取消和前后查询，不受订阅地区限制。订阅办理中的后续步骤沿用原订单代理。</small></label><label>同地区优先代理<select v-model="form.default_id"><option value="">按订阅地区自动分配</option><option v-for="p in proxies" :key="p.id" :value="p.id" :disabled="!p.enabled">{{p.name}} · {{regionLabel(p.country)}}{{p.enabled?'':'（停用）'}}</option></select><small>仅在订阅地区相同时优先使用；停用或占满时自动选择同地区其他代理，不跨地区分配。</small></label></template><div class="form-grid"><label v-for="f in fields[group]||[]" :key="f.k" :class="{span2:f.type==='textarea'}">{{f.n}}<input v-if="f.type==='switch'" class="toggle" type="checkbox" v-model="form[f.k]"/><textarea v-else-if="f.type==='textarea'" v-model="form[f.k]" rows="5" required></textarea><select v-else-if="f.type==='select'" v-model="form[f.k]"><option v-for="o in f.options" :key="o" :value="o">{{f.k==='default_country'?regionLabel(o):o}}</option></select><input v-else-if="f.type==='text'||f.type==='fixed'" v-model="form[f.k]" :readonly="f.type==='fixed'" :required="f.k!=='support_url'" maxlength="500"/><input v-else v-model.number="form[f.k]" type="number" :min="f.min" :max="f.max" :step="f.money?'0.01':'1'" required/></label></div><template v-if="group==='tiers'"><p>按累计充值门槛使用对应折扣，账户专属单价优先。金额门槛单位为分；discount 为原价百分比。</p><label>等级列表<textarea class="mono" v-model="jsonText" rows="12" spellcheck="false"></textarea></label></template><div class="form-footer"><button class="btn primary" :disabled="busy"><Save :size="16"/>{{busy?'保存中…':'保存配置'}}</button></div></form></template>

<style scoped>
.subscription-flow-settings .muted{margin:8px 0 16px}
.subscription-flow-summary{display:block}
.subscription-flow-summary b{display:block}
.subscription-flow-summary p{margin:8px 0 0}
@media(max-width:600px){.subscription-flow-settings .form-grid{grid-template-columns:1fr}}
</style>
